\label{thm:main-packing}
Let $G$ and $H$ be graphs, let $P\subseteqV(H)$ be a $2$-packing of $H$, and
put
\[
 r:=|P|,\qquad W:=V(H)\setminusN_H[P],\qquad s:=\gamma_H(W).
\]
Then
\begin{equation}
 \gamma(G\mathbin{\square}H)
 \geq \frac{r\gamma(G)}{3}
 +\frac{(r+s)(2\gamma(G)-\rho(G))}{3}.
 \label{eq:main-packing}
\end{equation}

\label{cor:asymmetric}
For all graphs $G$ and $H$,
\begin{equation}
 \gamma(G\mathbin{\square}H)
 \geq
 \frac{2\gamma(G)\gamma(H)+\rho(H)\gamma(G)-\rho(G)\gamma(H)}{3},
 \label{eq:asymmetric}
\end{equation}
and hence, by symmetry,
\begin{equation}
 \gamma(G\mathbin{\square}H)
 \geq
 \frac{2\gamma(G)\gamma(H)
 +|\rho(H)\gamma(G)-\rho(G)\gamma(H)|}{3}.
 \label{eq:symmetric}
\end{equation}

\label{thm:packing-function}
In the setting of Theorem~\ref{thm:main-packing},
\begin{equation}
 \gamma(G\mathbin{\square}H)
 \geq r\gamma(G)-\frac{r\rho^{\{2\}}(G)}8
 +\frac{s(3\gamma(G)-\rho^{\{2\}}(G))}{4}.
 \label{eq:packing-function}
\end{equation}
Consequently, for all graphs $G$ and $H$,
\begin{equation}
 \gamma(G\mathbin{\square}H)
 \geq
 \frac{2(3\gamma(G)-\rho^{\{2\}}(G))\gamma(H)
 +\rho(H)(2\gamma(G)+\rho^{\{2\}}(G))}{8}.
 \label{eq:packing-function-global}
\end{equation}

\label{lem:packing-L-empty}
For every $i\leq r$, we have $L_i=\varnothing$, and hence
$\gamma(G)\leq|D_i|$.

\label{lem:second-count}
\begin{align}
 a+\frac b2&\geq r\left(\gamma(G)-\frac{\rho(G)}2\right),
 \label{eq:second-rho}\\
 a+\frac b3&\geq r\left(\gamma(G)-\frac{\rho^{\{2\}}(G)}3\right).
 \label{eq:second-rho2}
\end{align}

\label{lem:leftover}
\begin{align}
 s\gamma(G)&\leq w+\frac12\sum_{i>r}|L_i|+\frac{s\rho(G)}2,
 \label{eq:leftover-rho}\\
 s\gamma(G)&\leq w+\frac13\sum_{i>r}|L_i|+\frac{s\rho^{\{2\}}(G)}3.
 \label{eq:leftover-rho2}
\end{align}
